+\begin{theorem}[Uncertainty propagation: $|\beta_0 - 1/T_0| \le \sigma$]
+\label{thm:IPhO2026Problems_problem_IPhO_2026_4_A_5:beta0_uncertainty_bound}
+\lean{IPhO2026_4_A_5.beta0_uncertainty_bound}
